var expected=JsonUtility.FromJson<Bulldozer.Player.Persistence.MiningSnapshot>(SessionState.GetString("Loop.MidExpected",""));var e=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerEquipment>();if(e.SavePath!=SessionState.GetString("Loop.MidPath",""))throw new System.Exception("Checkpoint save required");var s=e.Snapshot;var p=UnityEngine.Object.FindFirstObjectByType<Bulldozer.Player.MinerController>();p.autoMine=false;
var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);System.Func<Bulldozer.Player.Persistence.MiningSnapshot,int[]> all=q=>q.items.Concat(q.backpackItems).Concat(q.barrowItems).Concat(q.refineryInput).Concat(q.refineryOutput).Concat(q.loadingQueue).Concat(q.truckItems).Concat(q.groundDrops.Select(d=>d.item)).Select(i=>i%6).OrderBy(i=>i).ToArray();
check(s.coins==expected.coins&&s.damageLevel==expected.damageLevel&&s.speedLevel==expected.speedLevel&&s.capacityLevel==expected.capacityLevel,"Interrupted-session cash and upgrades restored exactly");check(s.depletedBlocks.SequenceEqual(expected.depletedBlocks)&&s.taskClaimedMask==expected.taskClaimedMask,"Broken rocks and optional claims survive interruption");check(all(s).SequenceEqual(all(expected)),"Every in-flight resource survives interruption, including refinery input and partial truck cargo");check(s.truckItems.SequenceEqual(expected.truckItems),"Partial truck cargo restored without duplicate sale");float began=Time.realtimeSinceStartup;EditorApplication.isPaused=false;Time.captureDeltaTime=1f/30;EditorApplication.CallbackFunction tick=null;tick=()=>{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}if(e.RefineryInputCount==0){var after=e.Snapshot;check(all(after).SequenceEqual(all(expected)),"Restored refinery finishes with no ore loss or duplication");check(after.taskRefined==expected.taskRefined+expected.refineryInput.Length,"Only pending input earns new refining progress");check(after.coins==expected.coins,"Resume does not repay previously claimed rewards");System.IO.File.WriteAllLines("Maintenance/Miner/full-loop-interruption-verification.txt",report);EditorApplication.update-=tick;Time.captureDeltaTime=0;EditorApplication.isPaused=true;return;}if(Time.realtimeSinceStartup-began>30){report.Add("FAIL restored refinery stalled");System.IO.File.WriteAllLines("Maintenance/Miner/full-loop-interruption-verification.txt",report);EditorApplication.update-=tick;Time.captureDeltaTime=0;EditorApplication.isPaused=true;}};EditorApplication.update+=tick;return "Checking real mid-production checkpoint after Play restart";
